{
  "PROP-57888860-asm-003": {
    "property_id": "PROP-57888860-asm-003",
    "audit_result": {
      "property_id": "PROP-57888860-asm-003",
      "classification": "vulnerability",
      "code_path": "beacon_node/beacon_chain/src/fetch_blobs/mod.rs::build_blob_sidecars::L434-437",
      "proof_trace": "Blobs from EL are wrapped with KzgVerifiedBlob::from_execution_verified() which skips KZG proof verification entirely. Same issue in v2 path where blobs_to_data_column_sidecars uses EL-provided proofs without validation before propagation.",
      "attack_scenario": "Malicious or compromised EL sends invalid blob-commitment pairs. CL accepts them without verification, propagates to network, causing consensus splits when honest nodes reject invalid blobs.",
      "checklist_id": "PROP-57888860-asm-003"
    },
    "text": "Engine API blob data is semi-trusted; blobs from EL must still pass KZG commitment verification.",
    "assertion": "forall blob from EL: verify_blob_kzg_proof(blob, commitment) == true before propagation",
    "covers": "SG-020",
    "severity": "MEDIUM",
    "type": "assumption"
  }
}

